"""Supplementary generated tables for Phase 3 (reporting only).

Reads ``aggregated/`` and ``raw/latency.csv.gz`` and writes Markdown tables to
``tables/``.  Contains no decision logic (that is ``h1.py`` / ``analysis.py``),
so adding tables here cannot change the pre-registered H1 outcome.
"""

from __future__ import annotations

import math
from pathlib import Path
from typing import Any

import pandas as pd

HEADER = ("<!-- GENERATED by taorg.experiments.phase3.report from aggregated/ artifacts "
          "— do not edit by hand. -->\n\n")
METHOD_ORDER = ("no_memory", "fixed_window", "ema", "gated_ema", "hmm")


def _ci(m: float, lo: float, hi: float, d: int = 3) -> str:
    if m is None or (isinstance(m, float) and math.isnan(m)):
        return "n/a"
    if lo is None or (isinstance(lo, float) and math.isnan(lo)):
        return f"{m:.{d}f}"
    return f"{m:.{d}f} [{lo:.{d}f}, {hi:.{d}f}]"


def _p(p: float) -> str:
    if p is None or (isinstance(p, float) and math.isnan(p)):
        return "—"
    return "<0.001" if p < 0.001 else f"{p:.3f}"


def effect_size_table(pairs: pd.DataFrame, labels: dict[str, str], budget: int) -> str:
    """Paired differences (Vis-Gated EMA − comparator) for H1 conditions at one budget."""
    lines = [HEADER, f"# Paired effect sizes — Vis-Gated EMA minus comparator, budget {budget} frames\n",
             "Bootstrap 95% CI over evaluation seeds; d_z = mean/SD of paired differences; "
             "p = Holm-adjusted Wilcoxon (registered family) for EMA/Fixed Window/HMM, raw Wilcoxon "
             "for No Memory (exploratory).\n"]
    sub = pairs[(pairs.family == "h1") & (pairs.budget == budget)]
    for cond in sub.condition.unique():
        lines += [f"\n## {cond}\n",
                  "| Gap | Comparator | ΔF1 [CI] | d_z | p | ΔDelay (frames) [CI] | ΔFPR [CI] | ΔChurn [CI] |",
                  "|---|---|---|---|---|---|---|---|"]
        c = sub[sub.condition == cond]
        for gap in sorted(c.gap.unique()):
            for comp in METHOD_ORDER:
                r = c[(c.gap == gap) & (c.comparator == comp)].set_index("metric")
                if r.empty:
                    continue
                f1, dl, fp, ch = (r.loc[m] for m in ("persistence_f1", "term_delay_mean",
                                                     "false_pers_mean", "churn_mean"))
                p = f1["p_holm"] if not math.isnan(f1["p_holm"]) else f1["p_wilcoxon"]
                dz = f1["dz"]
                dz_s = "n/a" if math.isnan(dz) else ("±inf" if math.isinf(dz) else f"{dz:.2f}")
                lines.append(
                    f"| {gap} | {labels[comp]} | {_ci(f1['mean_diff'], f1['ci_lo'], f1['ci_hi'])} | "
                    f"{dz_s} | {_p(p)} | {_ci(dl['mean_diff'], dl['ci_lo'], dl['ci_hi'], 2)} | "
                    f"{_ci(fp['mean_diff'], fp['ci_lo'], fp['ci_hi'])} | "
                    f"{_ci(ch['mean_diff'], ch['ci_lo'], ch['ci_hi'], 4)} |")
    return "\n".join(lines) + "\n"


def sweep_table(desc: pd.DataFrame, cfg: dict[str, Any], labels: dict[str, str],
                gap: int, budget: int) -> str:
    """Per-level metrics for the visibility-noise and flicker sweeps."""
    conds = cfg["conditions"]
    primary = next(n for n, c in conds.items() if c["role"] == "h1_primary")
    axes = {"visibility-flag error ρ": [(primary, 0.0)], "flicker q": [(primary, 0.0)]}
    for n, c in conds.items():
        v = c.get("visibility_noise") or {}
        if c.get("sweep_axis") == "visibility_noise" or (c["role"] == "h1_robustness" and v):
            axes["visibility-flag error ρ"].append((n, v.get("occluded_to_visible_prob")))
        if c.get("sweep_axis") == "flicker" or (c["role"] == "h1_robustness" and c.get("flicker_miss_prob")):
            axes["flicker q"].append((n, c.get("flicker_miss_prob")))
    lines = [HEADER, f"# Noise sweeps — gap {gap} frames, budget {budget} frames, condition-matched "
                     "tuning, mean [95% CI]\n"]
    for axis, pts in axes.items():
        pts = sorted(pts, key=lambda t: t[1])
        for metric, title, d in [("persistence_f1", "Persistence F1", 3),
                                 ("term_delay_mean", "Termination delay (frames)", 2),
                                 ("false_pers_mean", "False persistence rate", 3),
                                 ("churn_mean", "Churn rate", 4),
                                 ("diag_clean_alive_recall", "Clean-period recall (diag.)", 3)]:
            lines += [f"\n## {axis} — {title}\n",
                      "| Method | " + " | ".join(f"{lvl:g} ({c})" for c, lvl in pts) + " |",
                      "|---|" + "---|" * len(pts)]
            for m in METHOD_ORDER:
                cells = []
                for c, _ in pts:
                    r = desc[(desc.condition == c) & (desc.gap == gap) & (desc.budget == budget)
                             & (desc.method == m) & (desc.selection_kind == "matched")]
                    cells.append("n/a" if r.empty else _ci(r.iloc[0][f"{metric}__mean"],
                                                           r.iloc[0][f"{metric}__ci_lo"],
                                                           r.iloc[0][f"{metric}__ci_hi"], d))
                lines.append(f"| {labels[m]} | " + " | ".join(cells) + " |")
    return "\n".join(lines) + "\n"


def stress_table(desc: pd.DataFrame, cfg: dict[str, Any], labels: dict[str, str], budget: int) -> str:
    """Stress conditions with C0-tuned operating points."""
    stress = [n for n, c in cfg["conditions"].items() if c["role"] == "stress"]
    cols = [("persistence_f1", "F1", 3), ("term_delay_mean", "Delay", 2),
            ("false_pers_mean", "FPR", 3), ("churn_mean", "Churn", 4),
            ("diag_spurious_rate", "Spurious (diag)", 3), ("diag_recovery_lag", "Recov. lag (diag)", 2),
            ("diag_swap_recall", "Swap recall (diag)", 3), ("diag_ghost_edge_frames", "Ghost frames (diag)", 1)]
    lines = [HEADER, f"# Stress conditions — C0-tuned operating points, budget {budget} frames, "
                     "mean [95% CI] over evaluation seeds\n"]
    for cond in stress:
        lines += [f"\n## {cond}\n\n{cfg['conditions'][cond].get('description', '')}\n",
                  "| Gap | Method | " + " | ".join(t for _, t, _ in cols) + " |",
                  "|---|---|" + "---|" * len(cols)]
        sub = desc[(desc.condition == cond) & (desc.budget == budget)]
        for gap in sorted(sub.gap.unique()):
            for m in METHOD_ORDER:
                r = sub[(sub.gap == gap) & (sub.method == m)]
                if r.empty:
                    continue
                r = r.iloc[0]
                lines.append(f"| {gap} | {labels[m]} | " + " | ".join(
                    _ci(r[f"{k}__mean"], r[f"{k}__ci_lo"], r[f"{k}__ci_hi"], d) for k, _, d in cols) + " |")
    return "\n".join(lines) + "\n"


def mismatched_table(desc: pd.DataFrame, labels: dict[str, str], budget: int) -> str:
    """R1/R2 evaluated with condition-matched vs C0-tuned parameters."""
    rob = desc[desc.role == "h1_robustness"]
    lines = [HEADER, f"# Tuning mismatch — robustness conditions, budget {budget} frames\n",
             "Persistence F1 / termination delay, mean over seeds; 'matched' = tuned on the "
             "condition's own calibration seeds, 'C0-tuned' = parameters selected under oracle "
             "visibility (secondary analysis).\n"]
    for cond in rob.condition.unique():
        sub = rob[(rob.condition == cond) & (rob.budget == budget)]
        gaps = sorted(sub.gap.unique())
        lines += [f"\n## {cond}\n", "| Method | Tuning | " + " | ".join(f"gap {g}" for g in gaps) + " |",
                  "|---|---|" + "---|" * len(gaps)]
        for m in METHOD_ORDER:
            for kind, name in (("matched", "matched"), ("mismatched_C0", "C0-tuned")):
                r = sub[(sub.method == m) & (sub.selection_kind == kind)].set_index("gap")
                if r.empty:
                    continue
                lines.append(f"| {labels[m]} | {name} | " + " | ".join(
                    f"{r.loc[g, 'persistence_f1__mean']:.3f} / {r.loc[g, 'term_delay_mean__mean']:.1f}"
                    for g in gaps) + " |")
    return "\n".join(lines) + "\n"


def latency_table(lat: pd.DataFrame, labels: dict[str, str]) -> str:
    """Frozen latency aggregation: mean over videos of per-video statistics."""
    lines = [HEADER, "# Temporal-module latency (ms per frame), C0 instances, primary-budget points\n",
             "Aggregate = mean over evaluation instances of the per-video statistic (frozen §7). "
             "Synthetic scenes with 8 edges; absolute values are not representative of real "
             "scene graphs and depend on the machine.\n",
             "| Method | mean | median | p95 | p99 | instances |", "|---|---|---|---|---|---|"]
    for m in METHOD_ORDER:
        r = lat[lat.method == m]
        if r.empty:
            continue
        lines.append(f"| {labels[m]} | {r.latency_mean_ms.mean():.4f} | {r.latency_median_ms.mean():.4f} | "
                     f"{r.latency_p95_ms.mean():.4f} | {r.latency_p99_ms.mean():.4f} | {len(r)} |")
    return "\n".join(lines) + "\n"


def run_report(cfg: dict[str, Any], out_dir: Path) -> list[str]:
    """Write all supplementary tables; returns written paths."""
    agg, tab = out_dir / "aggregated", out_dir / "tables"
    tab.mkdir(parents=True, exist_ok=True)
    labels = cfg["method_labels"]
    B = int(cfg["primary_budget_frames"])
    G = int(cfg["representative_gap_frames"])
    desc = pd.read_csv(agg / "descriptive_selected.csv")
    pairs = pd.read_csv(agg / "paired_tests.csv")
    out = {
        "effect_sizes.md": "".join(effect_size_table(pairs, labels, int(b)) for b in cfg["budgets_frames"]),
        "sweeps.md": sweep_table(desc, cfg, labels, G, B),
        "stress.md": stress_table(desc, cfg, labels, B),
        "tuning_mismatch.md": mismatched_table(desc, labels, B),
    }
    lat_path = out_dir / "raw" / "latency.csv.gz"
    if lat_path.exists():
        out["latency.md"] = latency_table(pd.read_csv(lat_path), labels)
    written = []
    for name, text in out.items():
        (tab / name).write_text(text, encoding="utf-8")
        written.append(str(tab / name))
    return written
